def cosine_similarity(vec_a, vec_b):
    dot = sum(a * b for a, b in zip(vec_a, vec_b))
    norm_a = sum(a * a for a in vec_a) ** 0.5
    norm_b = sum(b * b for b in vec_b) ** 0.5
    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0
    return dot / (norm_a * norm_b)

def filter_chunks_by_threshold(chunks, threshold):
    filtered = [c for c in chunks if c.get('score', 0.0) >= threshold]
    return sorted(filtered, key=lambda x: x.get('score', 0.0), reverse=True)

def compute_mrr(rankings):
    if not rankings:
        return 0.0
    reciprocal_sum = sum(1.0 / r if r > 0 else 0.0 for r in rankings)
    return round(reciprocal_sum / len(rankings), 4)
